using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class MarinaContainerIndexRepair{static MarinaContainerIndexRepair(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("MarinaContainerIndexRepair.request"))return;File.Delete("MarinaContainerIndexRepair.request");foreach(string color in new[]{"Blue","Red","Ivory"}){var m=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scenes/Oasis/YachtPortAtlas/Meshes/Mobile detailed "+color+" freight container.asset");m.SetTriangles(Enumerable.Range(0,m.vertexCount).ToArray(),0);m.RecalculateBounds();m.Optimize();EditorUtility.SetDirty(m);}AssetDatabase.SaveAssets();}}
